// A model whose bulk is in the giant band: it plants its feet - no dash, no leap
// (the donor scripts' op2 mode 5/8 arms are dropped for it).
export const ANIM_GIANTS = new Set([
  "m024hoee", "m054mgdr", "m115muge", "m119tono", "m126brak", "m193grfo", "m208tota", "m212manm",
  "m215sman", "m224mdev", "m226okwa", "m236vvnd", "m237chmr", "m244skst", "m245infr", "m251apkr",
  "m281tiro", "m334mldr", "m337zamb", "m360antr", "m382armg", "m406tot2", "m407ton2", "m409man2",
  "m411mld2", "m426hoe2", "m432msd2", "m434ant2", "m439fuji", "m441raiz", "m442rgn1", "m466rgn2",
  "m467rgn3", "m470agry",
]);

/** The donor row for `folder` clip `clip`, or null when the model owns (or never misses) that clip. */
export function donorRow(folder, clip) {
  const gaps = folder ? ANIM_DONOR_GAPS[folder] : null;
  return (gaps && gaps[clip]) || null;
}

/** True when the model plants its feet: no dash / leap in its built clips. */
export function isGiant(folder) { return ANIM_GIANTS.has(folder); }
